package com.abhi.ganasuno.ui

import android.app.Activity
import android.content.Intent
import android.net.Uri
import android.widget.EditText
import android.widget.Toast
import com.abhi.ganasuno.data.*
import com.google.android.material.dialog.MaterialAlertDialogBuilder
import java.util.concurrent.Executor

/** Metadata browsing deliberately separates recordings from playable YouTube IDs. */
class MusicCatalogueTools(private val a:Activity,private val io:Executor,private val searchPublic:(String,String)->Unit,private val openChannel:(String,String)->Unit,private val searchMusic:(String)->Unit){
    private var contact="";private var generation=0
    private fun toast(s:String)=Toast.makeText(a,s,Toast.LENGTH_LONG).show()
    private fun choose(title:String,rows:List<String>,action:(Int)->Unit){if(rows.isEmpty()){toast("No matching metadata returned");return};MaterialAlertDialogBuilder(a).setTitle(title).setItems(rows.toTypedArray()){_,n->action(n)}.setNegativeButton("Close",null).show()}
    private fun ask(title:String,hint:String="",action:(String)->Unit){val e=EditText(a).apply{setSingleLine(true);this.hint=hint;isSaveEnabled=false};MaterialAlertDialogBuilder(a).setTitle(title).setView(e).setNegativeButton("Cancel",null).setPositiveButton("Continue"){_,_->val value=e.text.toString().trim();e.text.clear();if(value.isNotBlank())action(value)}.show()}
    private fun <T> task(run:(String)->T,done:(T)->Unit){if(contact.isBlank()){ask("MusicBrainz requires an application maintainer contact","Maintainer email (sent in User-Agent)"){raw->contact=Batch21.contact(raw).orEmpty();if(contact.isBlank())toast("Enter a valid maintainer email")else task(run,done)};return};val who=contact;val serial=++generation;toast("Fetching music metadata…");io.execute{val result=runCatching{run(who)};a.runOnUiThread{if(!a.isDestroyed&&!a.isFinishing&&generation==serial)result.onSuccess(done).onFailure{toast("MusicBrainz unavailable. Check network or provider limits.")}}}}
    private fun open(item:MusicCatalogue.Item){runCatching{a.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(Batch21.url(item.kind,item.id))))}.onFailure{toast("No browser available")}}
    private fun limit()=Batch21.limit(LibraryStore.option("home_limit",30))
    fun show(current:Song?=null){choose("MusicBrainz · songs, artists & releases",listOf("Search recordings / songs","Search artists","Search albums / singles / EPs","Recent releases by artist · last 30 days","Find versions of current song","Forget maintainer contact","Recent album / single / EP releases · all artists","Search public playlists","Search public music videos")){n->when(n){0,1,2->ask("Search music metadata"){q->val kind=listOf("recording","artist","release-group")[n];task({MusicCatalogue.search(it,kind,q,limit())}){rows("MusicBrainz results",it)}};3->ask("Artist name for recent releases"){q->task({MusicCatalogue.recent(it,q,limit())}){rows("Recent release groups · catalogue dates",it)}};4->{if(current==null||current.artist.isBlank())toast("Play a song with an artist name first")else task({MusicCatalogue.alternatives(it,current.title,current.artist,limit())}){rows("Candidate recording versions · verify edition",it)}};5->{contact="";generation++;toast("Session contact forgotten")};6->task({MusicCatalogue.recent(it,"",limit())}){rows("New release groups · last 30 days",it)};7,8->ask("Search public catalogue"){q->searchPublic(q,if(n==7)"playlist" else "video")}}}}
    private fun rows(title:String,items:List<MusicCatalogue.Item>){choose(title,items.map{listOf(it.title,it.artist,it.type,it.date,it.note).filter{v->v.isNotBlank()}.joinToString(" · ")}){item(items[it])}}
    private fun browse(title:String,kind:String,filter:String,id:String,offset:Int=0){task({MusicCatalogue.browsePage(it,kind,filter,id,offset,limit())}){page->val labels=page.items.map{listOf(it.title,it.artist,it.type,it.date,it.note).filter{v->v.isNotBlank()}.joinToString(" · ")}+if(page.next!=null)listOf("Next page →")else emptyList();choose("$title · from ${offset+1}",labels){n->if(n==page.items.size&&page.next!=null)browse(title,kind,filter,id,page.next)else item(page.items[n])}}}
    private fun artistChannel(e:MusicCatalogue.Item){val prefs=a.getSharedPreferences("artist_channels_v23",android.content.Context.MODE_PRIVATE);val old=prefs.getString(e.id,"").orEmpty();val options=if(Batch16.valid("channel",old))listOf("Browse linked channel","Replace channel","Unlink channel")else listOf("Link artist channel");choose("${e.title} · user-verified link",options){n->if(options[n]=="Browse linked channel")openChannel(old,e.title)else if(options[n]=="Unlink channel"){prefs.edit().remove(e.id).apply();toast("Artist channel unlinked")}else ask("Verify the artist independently, then enter channel ID or URL"){raw->val id=Batch23.artistChannel(raw);if(id==null)toast("Invalid channel ID")else{MaterialAlertDialogBuilder(a).setTitle("Link artist channel?").setMessage("${e.title} → $id. This is your own mapping, not a provider-verified identity.").setNegativeButton("Cancel",null).setPositiveButton("Link and browse"){_,_->prefs.edit().putString(e.id,id).apply();openChannel(id,e.title)}.show()}}}}
    private fun item(e:MusicCatalogue.Item){when(e.kind){
        "artist"->choose(e.title,listOf("Recordings / songs","Albums, singles and EPs","About artist","Open MusicBrainz page","Search music in GANASUNO","Featured on · recording appearances","Search public music videos","Link verified artist channel / browse uploads")){n->when(n){0->browse("${e.title} · recordings","recording","artist",e.id);1->browse("${e.title} · release groups","release-group","artist",e.id);2->task({MusicCatalogue.artistInfo(it,e.id)}){MaterialAlertDialogBuilder(a).setTitle(e.title).setMessage(it).setPositiveButton("Close",null).show()};3->open(e);4->searchMusic(e.title);5->browse("${e.title} · credited releases","release","track_artist",e.id);6->searchPublic(e.title,"video");7->artistChannel(e)}}
        "release-group"->choose(e.title,listOf("Browse release editions","Search music in GANASUNO","Open MusicBrainz page")){n->when(n){0->browse("${e.title} · editions","release","release-group",e.id);1->searchMusic("${e.title} ${e.artist}".trim());2->open(e)}}
        "release"->choose(e.title,listOf("Track listing","Open MusicBrainz page")){n->if(n==0)task({MusicCatalogue.release(it,e.id)}){r->choose("${r.title} · ${r.date} ${r.country}",r.tracks.map{t->"${t.number} ${t.title} · ${t.artist}"}){i->val t=r.tracks[i];searchMusic("${t.title} ${t.artist}".trim())}}else open(e)}
        else->choose(e.title,listOf("Search playable matches in GANASUNO","Open MusicBrainz recording")){n->if(n==0)searchMusic("${e.title} ${e.artist}".trim())else open(e)}
    }}
}
